import time
from collections import OrderedDict


class TTLLRUCache:
    """LRU cache with optional TTL expiry (lazy, no background threads)."""

    def __init__(self, capacity, default_ttl=None, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        self._capacity = capacity
        self._default_ttl = default_ttl
        self._clock = clock
        self._data = OrderedDict()  # key -> (value, expires_at or None)
        self._hits = 0
        self._misses = 0
        self._evictions = 0
        self._expirations = 0

    def _is_expired(self, expires_at, now=None):
        if expires_at is None:
            return False
        if now is None:
            now = self._clock()
        return now >= expires_at

    def _purge_expired(self):
        now = self._clock()
        dead = [k for k, (_, exp) in self._data.items()
                if self._is_expired(exp, now)]
        for k in dead:
            del self._data[k]
            self._expirations += 1

    def put(self, key, value, ttl=None):
        if ttl is None:
            ttl = self._default_ttl
        expires_at = None if ttl is None else self._clock() + ttl
        if key in self._data:
            self._data[key] = (value, expires_at)
            self._data.move_to_end(key)
            return
        if len(self._data) >= self._capacity:
            self._purge_expired()
            if len(self._data) >= self._capacity:
                self._data.popitem(last=False)
                self._evictions += 1
        self._data[key] = (value, expires_at)

    def get(self, key):
        try:
            value, expires_at = self._data[key]
        except KeyError:
            self._misses += 1
            raise KeyError(key) from None
        if self._is_expired(expires_at):
            del self._data[key]
            self._expirations += 1
            self._misses += 1
            raise KeyError(key)
        self._hits += 1
        self._data.move_to_end(key)
        return value

    def __contains__(self, key):
        try:
            _, expires_at = self._data[key]
        except KeyError:
            return False
        if self._is_expired(expires_at):
            del self._data[key]
            self._expirations += 1
            return False
        return True

    def __len__(self):
        self._purge_expired()
        return len(self._data)

    def stats(self):
        return {
            "hits": self._hits,
            "misses": self._misses,
            "evictions": self._evictions,
            "expirations": self._expirations,
        }
